async function readFailedChildMessages(client, sessionId, directory) {
  if (!client || !sessionId)
    return;
  let timer;
  try {
    const response = await Promise.race([
      client.session.messages({
        path: { id: sessionId },
        query: { directory, limit: FAILED_CHILD_MESSAGE_LIMIT }
      }),
      new Promise((resolve) => {
        timer = setTimeout(() => resolve(null), FAILED_CHILD_READ_TIMEOUT_MS);
      })
    ]);
    if (response === null)
      return;
    const messages = normalizeSDKResponse(response, [], {
      preferResponseOnMissingData: true
    });
    return Array.isArray(messages) ? messages : undefined;
  } catch (error) {
    log2(`[dreamer] failed-child evidence read failed for ${sessionId}: ${String(error)}`);
    return;
  } finally {
    if (timer)
      clearTimeout(timer);
  }
}

