// ../plugin/src/plugin/boot-deadline.ts
async function runBootPhaseWithDeadline(phase, operation, timeoutMs, report, deadlineDescription = `its ${timeoutMs}ms deadline`) {
  const startedAt = performance.now();
  const deadline = startBootDeadline(timeoutMs, () => report(`[magic-context] boot phase '${phase}' reached ${deadlineDescription} while a schema migration runs off the main thread; waiting for the migration, which does not count against the deadline`));
  const running = Promise.resolve().then(operation);
  const timeout = deadline.expired.then(() => {
    const elapsedMs = performance.now() - startedAt;
    report(`[magic-context] boot phase '${phase}' exceeded ${deadlineDescription}; host startup will continue with Magic Context fail-closed`);
    return { status: "timed_out", elapsedMs, pending: running };
  });
  const completed = running.then((value) => ({
    status: "completed",
    value,
    elapsedMs: performance.now() - startedAt
  }));
  try {
    const result = await Promise.race([completed, timeout]);
    if (result.status === "timed_out") {
      running.catch((error) => {
        report(`[magic-context] boot phase '${phase}' rejected after its deadline: ${error instanceof Error ? error.message : String(error)}`);
      });
    }
    return result;
  } finally {
    deadline.cancel();
  }
}

// src/pi-boot-deadline.ts
async function bootPiRuntimeWithDeadline(args) {
  let runtimeStarted = false;
  let runtimeStart = null;
  const startRuntimeOnce = async (value) => {
    if (runtimeStarted)
      return;
    if (runtimeStart)
      return runtimeStart;
    runtimeStart = (async () => {
      await args.startRuntime(value);
      runtimeStarted = true;
    })();
    try {
      await runtimeStart;
    } finally {
      if (!runtimeStarted)
        runtimeStart = null;
    }
  };
  const phase = await runBootPhaseWithDeadline("pi runtime", async () => {
    const value = await args.openStorage();
    if (value !== null)
      await startRuntimeOnce(value);
    return value;
  }, args.deadlineMs, args.report);
  if (phase.status === "completed") {
    if (phase.value === null) {
      args.registerFailClosed({
        reason: args.unavailableReason(),
        tryReopen: args.openStorage,
        onRecovered: startRuntimeOnce
      });
      return { status: "unavailable" };
    }
    return { status: "ready" };
  }
  let pendingOpen = phase.pending;
  const surface = args.registerFailClosed({
    reason: args.deadlineReason,
    tryReopen: () => pendingOpen ?? args.openStorage(),
    onRecovered: startRuntimeOnce
  });
  const lateAdoption = phase.pending.then((value) => value === null ? false : surface.adoptRecovered(value)).catch(() => false).finally(() => {
    pendingOpen = null;
  });
  return { status: "timed_out", lateAdoption };
}

// src/pi-native-config.ts
import {
  copyFileSync,
  existsSync as existsSync12,
  lstatSync,
  mkdirSync as mkdirSync3,
  readFileSync as readFileSync12,
  readlinkSync,
  renameSync as renameSync2,
  rmSync as rmSync3,
  statSync as statSync7,
  symlinkSync
} from "node:fs";
import { homedir as homedir3 } from "node:os";
import { dirname as dirname5, isAbsolute as isAbsolute3, join as join16 } from "node:path";
function homeDir() {
  if (process.platform === "win32") {
    return process.env.USERPROFILE || process.env.HOME || homedir3();
  }
  return process.env.HOME || homedir3();
}
var PI_NATIVE_PATH = join16(homeDir(), ".pi", "agent", "extension-configs", "magic-context", "magic-context.jsonc");
function configHome() {
  const xdg = process.env.XDG_CONFIG_HOME;
  return xdg && isAbsolute3(xdg) ? xdg : join16(homeDir(), ".config");
}
function cortexKitPath() {
  return join16(configHome(), "cortexkit", "magic-context.jsonc");
}
function isSymlink(path) {
  try {
    return lstatSync(path).isSymbolicLink();
  } catch {
    return false;
  }
}
