// src/strip-tag-prefix.ts
function stripTagPrefixFromAssistantMessage(message) {
  if (message.role !== "assistant")
    return false;
  if (!Array.isArray(message.content))
    return false;
  let mutated = false;
  for (const part of message.content) {
    if (part === null || typeof part !== "object" || part.type !== "text") {
      continue;
    }
    const textPart = part;
    if (typeof textPart.text !== "string")
      continue;
    const stripped = stripPersistedAssistantText(textPart.text);
    if (stripped !== textPart.text) {
      textPart.text = stripped;
      mutated = true;
    }
  }
  return mutated;
}

// src/subagent-host-tools.ts
function registerPiSubagentHostTools(pi, harness) {
  if (harness !== "omp")
    return;
  let active = false;
  pi.on("session_start", () => {
    active = true;
    configurePiSubagentHostTools(() => {
      if (!active)
        return;
      if (typeof pi.getAllTools === "function") {
        return pi.getAllTools().map((tool) => tool.name);
      }
      if (typeof pi.getActiveTools === "function")
        return pi.getActiveTools();
      return;
    });
  });
  pi.on("session_shutdown", () => {
    active = false;
  });
}

// src/timeout.ts
function withTimeout(p, ms) {
  let handle;
  const timeout = new Promise((resolve) => {
    handle = setTimeout(() => resolve(undefined), ms);
    handle.unref?.();
  });
  return Promise.race([p, timeout]).finally(() => {
    if (handle)
      clearTimeout(handle);
  });
}

